#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int p, k;
    std::cin >> p >> k;
    std::vector<int> a(p, 0);
    int sets = 0;
    for (int i = 0; i < p; ++i) {
        if (a[i] == 0) {
            sets += 1;
            int r = i;
            while (a[r] == 0) {
                a[r] = 1;
                r = static_cast<int>(fmod(r * k, p));
            }
        }
    }
    if (k == 0) {
        sets = p;
    } else if (k == 1) {
        sets = p + 1;
    }
    long long res = 1;
    const long long big = 1000000007;
    for (int _ = 0; _ < sets - 1; ++_) {
        res = static_cast<long long>(fmod(res * p, big));
    }
    std::cout << res << std::endl;
    return 0;
}
